# Nature Genetics-style manuscript sections for the CNV x BMI growth / social-communication analyses (JS / Claude 2026-10-26).
# Builds manuscript_materials_2026-10-24/NatGenet_sections_2026-10-26.docx (and .md) with three parts:
#   1. Main text (~700 words) + Figure 1 legend;  2. Methods (main figure);  3. Supplementary Information
#   (Supplementary Results, Supplementary Methods, Supplementary Figs. 1-5 with legends, Supplementary Tables 1-9 legends, references).
# Also writes Supplementary_Tables.xlsx (sheets renamed Supplementary Table 1-9). Numbers are typed in from the tables in this folder;
# regenerate the tables first after any data change, then re-check the numbers here. Run: Rscript 33_natgen_sections.R, then
# finish_report.ps1 <docx> (strips template heading numbers, fixes tables, exports PDF). References are given as PubMed IDs.
suppressPackageStartupMessages({ library(officer); library(data.table); library(openxlsx) })
HERE <- "C:/Users/Jonathan Sebat/sebatlab Dropbox/Manuscripts/PGC_joint_submission/Molly/CNV_ASD_growth_analysis/CNV_growth_trajectories"
MAT <- file.path(HERE, "manuscript_materials_2026-10-24"); OUT <- file.path(MAT, "NatGenet_sections_2026-10-26.docx"); MDOUT <- sub("docx$", "md", OUT)
d <- read_docx(); md <- character(0)
FF <- "Cambria"; sup <- fp_text(vertical.align = "superscript", font.family = FF); ital <- fp_text(italic = TRUE, font.family = FF); bold <- fp_text(bold = TRUE, font.family = FF)
# inline markup: ^1,2^ superscript (reference numbers); *x* italic (P, n, r, t); **x** bold
runs <- function(t) { parts <- regmatches(t, gregexpr("\\^[^^]+\\^|\\*\\*[^*]+\\*\\*|\\*[^*]+\\*", t))[[1]]; rest <- strsplit(t, "\\^[^^]+\\^|\\*\\*[^*]+\\*\\*|\\*[^*]+\\*")[[1]]
  out <- list(); for (i in seq_along(rest)) { if (nzchar(rest[i])) out[[length(out) + 1]] <- ftext(rest[i], fp_text(font.family = FF))
    if (i <= length(parts)) { p <- parts[i]; out[[length(out) + 1]] <- if (startsWith(p, "^")) ftext(gsub("\\^", "", p), sup) else if (startsWith(p, "**")) ftext(gsub("\\*", "", p), bold) else ftext(gsub("\\*", "", p), ital) } }
  if (length(rest) < length(parts)) { p <- parts[length(parts)]; out[[length(out) + 1]] <- if (startsWith(p, "^")) ftext(gsub("\\^", "", p), sup) else if (startsWith(p, "**")) ftext(gsub("\\*", "", p), bold) else ftext(gsub("\\*", "", p), ital) }
  do.call(fpar, out) }
H1 <- function(t) { d <<- body_add_par(d, t, style = "heading 1"); md <<- c(md, "", paste("#", t), "") }
H2 <- function(t) { d <<- body_add_par(d, t, style = "heading 2"); md <<- c(md, "", paste("##", t), "") }
H3 <- function(t) { d <<- body_add_fpar(d, fpar(ftext(t, bold)), style = "Normal"); md <<- c(md, "", paste0("**", t, "**"), "") }
P <- function(t) { d <<- body_add_fpar(d, runs(t), style = "Normal"); md <<- c(md, gsub("\\^([^^]+)\\^", "^\\1^", t), "") }
BR <- function() d <<- body_add_break(d)
IMG <- function(f, w = 6.5) { con <- file(f, "rb"); readBin(con, "raw", 16); wh <- readBin(con, "integer", 2, size = 4, endian = "big"); close(con); d <<- body_add_img(d, f, width = w, height = w * wh[2] / wh[1]); md <<- c(md, paste0("![](", basename(f), ")"), "") }
TB <- function(df) { d <<- body_add_table(d, value = df, style = "table_template", header = TRUE); d <<- body_add_par(d, "", style = "Normal")
  md <<- c(md, paste0("| ", paste(names(df), collapse = " | "), " |"), paste0("|", paste(rep("---", ncol(df)), collapse = "|"), "|"), apply(df, 1, function(r) paste0("| ", paste(r, collapse = " | "), " |")), "") }
wc <- function(x) sum(lengths(strsplit(gsub("\\^[^^]+\\^", "", x), "\\s+")))

# ======================================================================================================== front matter
d <- body_add_fpar(d, fpar(ftext("Body mass, growth and social-communication phenotypes in carriers of 16p11.2 and 22q11.2 CNVs: manuscript sections", fp_text(bold = TRUE, font.size = 15, font.family = FF))), style = "Normal")
md <- c(md, "# Body mass, growth and social-communication phenotypes in carriers of 16p11.2 and 22q11.2 CNVs: manuscript sections", "")
P("Draft sections for insertion into the Nature Genetics manuscript, prepared 2026-10-26 (J. Sebat; analysis with Claude). Part 1, main text (target ~700 words) and the Figure 1 legend; Part 2, Methods for the main figure; Part 3, Supplementary Information (Supplementary Results, Supplementary Methods, Supplementary Figs. 1-5, Supplementary Tables 1-9). References are numbered in order of first citation and given with PubMed IDs. All numbers are provisional until the corrected growth records and new participants are added (see HANDOFF_2026-10-26.md); figure panel letters will be converted to lower case in the final artwork. Items marked [to confirm] need author input.")

# ======================================================================================================== PART 1: main text
BR(); H1("Part 1. Main text")
H2("Body mass is coupled to head growth and social-communication impairment in CNV carriers")
MAIN <- c(
"Recurrent copy-number variants (CNVs) at 16p11.2 and 22q11.2 have reciprocal effects on body mass and head size: 16p11.2 deletion carriers are prone to obesity and macrocephaly and duplication carriers to underweight and microcephaly^1-3^, and 22q11.2 deletion is associated with obesity in adulthood^4^. Whether body mass is itself coupled to growth and to the neurodevelopmental phenotype of carriers is not known. We therefore asked whether, within carriers, body mass index (BMI) is associated with height, head circumference and social-communication traits beyond the relationships seen in the general population.",
"We analysed carriers of 16p11.2 (BP4-BP5) and 22q11.2 (A-D) deletions and duplications from the G2MH, Simons VIP, Simons Searchlight and Cardiff cohorts (*n* = 118-358 per CNV), unaffected non-carrier relatives from the Simons Simplex Collection (SSC)^5^ and Simons VIP^6^ (*n* = 5,708) and autistic SSC probands without a CNV (*n* = 2,074). Height, head circumference and BMI were expressed as age- and sex-standardized *z* scores^7-9^ and modelled with generalized additive models (GAMs) in which the BMI effect within each group is an age-adjusted slope (s.d. of outcome per s.d. of BMI) and the carrier-control contrast (CNV x BMI) is the age-adjusted difference in that slope (Fig. 1, Supplementary Tables 1 and 2).",
"Height in carriers differed from controls by a constant shift (up to -0.70 s.d. in 16p11.2 deletion), but the relationship between BMI and height was the same as in controls for every CNV (CNV x BMI, *P* = 0.24-0.99; Fig. 1a-e). Head circumference rose with BMI in every group, including controls (+0.36 s.d. per s.d.), and 16p11.2 deletion carriers showed an excess over this general relationship (+0.13 s.d. per s.d., s.e. 0.06, *P* = 0.021; Fig. 1g). No other CNV did (*P* = 0.39-0.73; heterogeneity across CNVs *P* = 0.21), and the excess was also present relative to autistic SSC probands (+0.17, *P* = 0.002). In longitudinal series from children, higher BMI at a visit preceded faster head growth to the next visit (pooled carriers +0.10 s.d. per s.d., *P* = 6.7 x 10^-4^), whereas a prospective effect on height growth was confined to children under 8 years (Supplementary Fig. 1, Supplementary Table 3). Within the overgrowth CNVs (16p11.2 deletion and 22q11.2 duplication), carriers with autism had larger heads than carriers without (+0.45 s.d., *P* = 0.022; *P* = 0.046 versus the proband-sibling difference in the SSC), but BMI did not differ by autism status in any CNV group (Supplementary Fig. 5, Supplementary Tables 7 and 8).",
"Social-communication impairment also tracked body mass in carriers. Social Responsiveness Scale (SRS)^10^ and Social Communication Questionnaire (SCQ)^11^ scores rose with BMI in carriers of every CNV, with slopes exceeding those of unaffected relatives for SCQ in all four CNVs (CNV x BMI +0.26 to +0.48 s.d. per s.d., *P* <= 0.034) and for SRS in three (+0.17 to +0.50, *P* = 0.044 to 8.4 x 10^-6^; Fig. 1k-t). Pooled across CNVs the excess was +0.21 s.d. per s.d. for SRS (*P* = 1.6 x 10^-6^) and +0.34 for SCQ (*P* = 4.8 x 10^-5^), with no heterogeneity between CNVs (*P* = 0.61 and 0.96). Neither unaffected relatives (+0.01) nor autistic SSC probands without a CNV (+0.03; *P* versus relatives 0.42 and 0.79) showed any BMI slope, so the association is a property of CNV carriers rather than of autism (Supplementary Fig. 2). Cognitive performance (Penn CNB) was unrelated to BMI (Supplementary Figs. 3 and 4).",
"These associations were not explained by sex, polygenic background, medication or diagnosis. Adjusting the CNV x BMI contrasts for sex and for polygenic scores for childhood obesity, adult BMI, height and autism, singly or together, left the estimates unchanged on the same individuals, and the effects were present within each sex and within both halves of every polygenic-score distribution (Supplementary Tables 4 and 5); no adequately powered modifier x BMI interaction survived correction (Supplementary Table 6). Psychotropic medication (29-33% of carriers) was associated with the traits but not with BMI, and the slopes were unchanged after adjustment for medication class or restriction to unmedicated carriers (Supplementary Table 9). Together, these results show that in carriers of these CNVs body mass is coupled to head growth, specifically in 16p11.2 deletion, and to the severity of social-communication impairment across all four CNVs, in a way that is not seen in the general population or in idiopathic autism.")
for (p in MAIN) P(p)
P(sprintf("[Word count of the five paragraphs above: %d.]", wc(MAIN)))

H3("Figure 1 | Body mass, growth and social-communication phenotypes in carriers of 16p11.2 and 22q11.2 CNVs and in unaffected relatives.")
P("**a-j**, Height *z* score (WHO; **a-e**) and head-circumference *z* score (UK90; **f-j**) against age in unaffected non-carrier relatives (**a**,**f**; SSC designated siblings and parents and Simons VIP non-carrier family members without autism) and in carriers of 16p11.2 deletion (**b**,**g**), 16p11.2 duplication (**c**,**h**), 22q11.2 deletion (**d**,**i**) and 22q11.2 duplication (**e**,**j**), for individuals with BMI at or above the 70th centile (red) or at or below the 30th centile (teal); lines are generalized additive model (GAM) smooths with 95% confidence bands. Printed values in **b-e** and **g-j** are two-sided *P* values from GAMs fitted to all individuals with continuous BMI, not only the plotted tails: CNV x BMI, the age-adjusted difference between carriers and controls in the slope of the outcome on BMI *z*; CNV x age x BMI, whether that difference varies with age (tensor-product interaction). **k-t**, SRS total (*z* relative to SSC unaffected relatives; **k-o**) and SCQ lifetime total (*z* relative to SSC siblings; **p-t**), adjusted for age within group, against BMI *z*; points are coloured by BMI tail as above (grey, 30th-70th centile); black line and band, linear fit with 95% CI; diamonds, mean +/- s.e.m. in BMI bins (< -1, -1 to 0, 0 to 1, 1 to 2, > 2 s.d.); dashed grey line, the fit in unaffected relatives. **k** and **p** also show SSC probands with autism and no CNV (black). Printed values are the within-group BMI slope (s.d. of trait per s.d. of BMI; GAM *y* ~ s(age) + BMI) and the two-sided *P* value for its difference from unaffected relatives (model as in **a-j**). Bold, nominal *P* < 0.05. *n* (controls; 16p11.2 del, 16p11.2 dup, 22q11.2 del, 22q11.2 dup): height 5,708; 358, 199, 357, 118. Head circumference 5,680; 211, 125, 242, 92. SRS 5,486 (probands 2,065); 79, 34, 208, 67. SCQ 1,134 (probands 1,503); 60, 21, 170, 50. Heterogeneity of the age-adjusted BMI slope across the four CNV groups (Wald test of the locus x BMI interaction within carriers): height *P* = 0.75, head circumference *P* = 0.21, SRS *P* = 0.61, SCQ *P* = 0.96. BMI *z*: WHO for children; for adults, centile relative to the pooled non-carrier adults of the clinical cohorts mapped to *z*. Carriers with and without autism are combined. All tests are two-sided; no adjustment for multiple comparisons was applied to the printed *P* values.")
IMG(file.path(HERE, "fig_main_v3.png"), w = 5.4)

# ======================================================================================================== PART 2: methods
BR(); H1("Part 2. Methods (main figure)")
H3("Participants")
P("Carriers of 16p11.2 proximal (BP4-BP5) deletions and duplications and 22q11.2 (LCR A-D) deletions and duplications were drawn from the Genes to Mental Health (G2MH) network, the Simons Variation in Individuals Project (Simons VIP)^6^, Simons Searchlight and the Cardiff University cohort [to confirm: CNV calling and inclusion criteria per cohort; ethics approvals and consent statement for each site]. Unaffected controls were non-carrier designated siblings and parents from the Simons Simplex Collection (SSC)^5^ and non-carrier family members without autism from Simons VIP. SSC probands with autism and no CNV formed a separate autism comparison group. Analyses used participants aged 2-65 years and, for each individual, the most recent visit at which the outcome and BMI were both available. Autism diagnosis in carriers was taken from the G2MH subject table and the Simons VIP diagnostic summary; all SSC probands carry an autism diagnosis by design. Social-communication measures were the SRS-2 total raw score^10^ (parent report for children, adult self or informant report) and the SCQ lifetime total^11^.")
H3("Anthropometric measures")
P("Height, weight and head circumference were taken from the clinical and research records of each cohort. Before scoring, implausible values were screened as described in the Supplementary Methods (heights recorded in metres were converted; heights outside 60-230 cm, BMI outside 10-70 kg m^-2^, |height *z*| > 5, child |BMI *z*| > 5 and head circumference outside 30-70 cm or |*z*| > 5 were set to missing). Height was standardized against the WHO child growth standards and the WHO 2007 reference^7,8^; head circumference against the UK 1990 reference^9^, with adults scored at 18 years; BMI in children against the WHO reference and in adults as a centile relative to the pooled non-carrier adults of the clinical cohorts, mapped to a *z* score. SRS and SCQ totals were expressed as *z* scores relative to SSC unaffected relatives and SSC siblings, respectively. For SSC relatives, whose tabulated ages refer to a single snapshot date, age at the study visit was reconstructed from the proband's age at evaluation and the birth-month difference (Supplementary Methods).")
H3("Statistical analysis")
P("All models were generalized additive models (GAMs) fitted by restricted maximum likelihood in mgcv^12^ (R 4.6.1). BMI entered every model as a continuous *z* score; the 70th and 30th centile split in Fig. 1 is for display only. Within a group, the BMI effect was the coefficient of BMI in *y* ~ BMI + s(age), in s.d. of outcome per s.d. of BMI, and the age dependence of that effect was tested with a tensor-product interaction, *y* ~ s(age) + s(BMI) + ti(age, BMI). Carriers were compared with a reference group (unaffected relatives, or SSC probands) in a single model, *y* ~ CNV + s(age, by = CNV) + s(age, by = BMI) + CNV:BMI, in which the CNV main effect is the age-adjusted mean shift and the CNV:BMI coefficient (CNV x BMI) is the age-adjusted difference in BMI slope; the age dependence of that difference (CNV x age x BMI) was tested by adding ti(age, BMI) and ti(age, BMI, by = CNV) and reporting the carrier-specific tensor product. Pooled analyses (all CNVs; overgrowth, 16p11.2 deletion plus 22q11.2 duplication; undergrowth, 16p11.2 duplication plus 22q11.2 deletion) included locus as a covariate. Heterogeneity of the BMI slope across the four CNV groups was tested within carriers as the Wald test of the locus x BMI interaction in *y* ~ s(age, by = locus) + locus + BMI + locus:BMI. For SRS and SCQ, whose BMI effects did not depend on age, the trait is plotted against BMI after removal of the within-group age smooth. All tests were two-sided and *P* values are reported without adjustment for multiple comparisons; the heterogeneity tests and the sensitivity analyses in the Supplementary Information address the specificity of the findings. Sample sizes are given in the figure legend and in Supplementary Tables 1 and 2; no statistical method was used to predetermine sample size.")
H3("Sensitivity analyses")
P("The robustness of the main-figure results to sex, polygenic background, psychotropic medication, autism diagnosis and the plausibility screen, the longitudinal (prospective) analyses, the comparison of carriers with and without autism, and the cognitive analyses are described in the Supplementary Methods and Supplementary Results.")
H3("Reporting summary")
P("Further information on research design is available in the Nature Portfolio Reporting Summary linked to this article [to be completed].")
H3("Data availability")
P("SSC and Simons VIP/Searchlight phenotype data are available to approved researchers through SFARI Base (https://base.sfari.org). G2MH phenotype data are available through the G2MH network [to confirm: NDA collection or data-access route]. Participant-level growth, phenotype and polygenic-score tables used here contain identifiers and are held in the controlled analysis data folder; summary statistics for every test are provided in Supplementary Tables 1-9.")
H3("Code availability")
P("All analysis code, figure scripts, summary tables and the analysis report are available at https://github.com/jsebat/cnv-growth-bmi (scripts 00-33; the main figure is produced by 25_main_figure_v3.R and Supplementary Tables 1 and 2 by 28_supp_tables.R).")

# ======================================================================================================== PART 3: supplementary information
BR(); H1("Part 3. Supplementary Information")
H2("Supplementary Results")
H3("Prospective effects of body mass on growth")
P("In carriers under 18 years with repeated measures, higher BMI at a visit preceded faster height growth to the next visit only in early childhood: in 16p11.2 deletion carriers the age-varying effect differed from zero (*P* = 0.006), the all-ages coefficient was +0.09 s.d. of height *z* per s.d. of BMI *z* (s.e. 0.04, *t* = 2.1, *P* = 0.036) and the effect was concentrated below 8 years (pooled carriers, < 8 y window +0.13, *t* = 2.9, *P* = 0.005; 8-13 y +0.01; 13-18 y -0.07). For head circumference the prospective effect was positive at all ages (16p11.2 deletion +0.08, *t* = 2.1, *P* = 0.038; pooled carriers +0.10, *t* = 3.4, *P* = 6.7 x 10^-4^; age-varying *P* = 7.5 x 10^-4^) (Supplementary Fig. 1, Supplementary Table 3).")
H3("Autism diagnosis within CNV group")
P("Head circumference was larger in carriers with than without an autism diagnosis in the overgrowth CNVs (pooled 16p11.2 deletion and 22q11.2 duplication: +0.45 s.d., *P* = 0.022, *n* = 188 without and 96 with autism; 16p11.2 deletion +0.41, *P* = 0.074; 22q11.2 duplication +0.59, *P* = 0.16) but not in the undergrowth CNVs (-0.05, *P* = 0.8); SSC probands also had slightly larger heads than their siblings (+0.14, *P* = 0.0014). Tested as an interaction, the autism effect in the overgrowth CNVs exceeded the proband-sibling difference (+0.35 s.d., s.e. 0.17, *P* = 0.046). Height did not differ by autism status in any group (all *P* > 0.07), and BMI did not differ by autism status within any CNV group (per locus +0.10 to +0.16 s.d., *P* = 0.43-0.78; interaction with carrier status *P* > 0.6 throughout), whereas SSC probands were marginally heavier than their siblings (+0.11, *P* = 0.032). The BMI effects in Fig. 1 are therefore not a by-product of autistic carriers being heavier. Adding polygenic scores for childhood obesity, adult BMI, height and autism, singly or together, to the age- and sex-adjusted models left all of these contrasts unchanged (Supplementary Fig. 5, Supplementary Tables 7 and 8).")
H3("Cognitive performance")
P("Penn Computerized Neurocognitive Battery^13,14^ accuracy and speed, available for G2MH carriers only, showed no reproducible association with BMI for any subtest or total (accuracy total: 16p11.2 deletion +0.02, 16p11.2 duplication -0.14 (*P* = 0.074), 22q11.2 deletion -0.02, 22q11.2 duplication +0.06 s.d. per s.d.; heterogeneity across CNVs *P* = 0.11). The negative slope in 16p11.2 duplication carriers had been nominally significant (-0.15, *P* = 0.015) before the plausibility screen and rested on a single carrier with a recorded BMI of 9.2 kg m^-2^ (Supplementary Figs. 3 and 4, Supplementary Table 2).")
H3("Sex and polygenic background")
P("In the subset with polygenic scores (G2MH carriers and SSC controls), the CNV x BMI contrasts were essentially unchanged by adjustment for sex, for each polygenic score with its BMI interaction, for all four scores, or for all four plus sex, on the same individuals: SRS, all CNVs, +0.192 (s.e. 0.048, *P* = 5.8 x 10^-5^) unadjusted and +0.198 (*P* = 3.6 x 10^-5^) fully adjusted; SCQ, all CNVs, +0.318 (*P* = 5.0 x 10^-4^) and +0.312 (*P* = 7.1 x 10^-4^); head circumference, 16p11.2 deletion, +0.130 (*P* = 0.086; weaker than in the full sample because Simons VIP, Searchlight and Cardiff carriers are unscored) and +0.151 (*P* = 0.041) (Supplementary Table 5). The carrier-versus-control slopes were present in both sexes and in both halves of every polygenic-score split (Supplementary Table 4). Of 206 modifier x BMI interaction tests, 47 had at least 80% power to detect an interaction as large as the carriers' own BMI effect; eleven were nominally significant (about two expected by chance, although the tests are correlated) and none survived correction for 47 tests (smallest *P* = 0.017). The only directionally consistent signal was a stronger BMI-growth coupling with higher adult-BMI polygenic score (height, all CNVs, +0.088 per s.d. of score, *P* = 0.017; head circumference +0.089, *P* = 0.031) (Supplementary Table 6).")
H3("Psychotropic medication")
P("Current psychotropic medication was recorded for 85-92% of G2MH carriers and used by 29-33% (antipsychotics 5-7%). Medication classes were strongly associated with the traits (antipsychotic users: SRS +2.3 s.d., SCQ +3.5 s.d., CNB accuracy -0.6 s.d.) but not with BMI (antipsychotics -0.2 s.d., *P* = 0.5; any psychotropic +0.3, *P* = 0.09), and the within-carrier BMI slopes were unchanged by adjustment for medication classes or by restriction to unmedicated carriers: SRS, all CNVs, +0.22, +0.19 and +0.23; SCQ +0.35, +0.37 and +0.38; head circumference, 16p11.2 deletion, +0.47, +0.48 and +0.50; height, 16p11.2 deletion, +0.31, +0.32 and +0.27 (Supplementary Table 9).")
H3("Effect of the plausibility screen")
P("Screening removed 106 visit records from 95 individuals. SRS, SCQ and head-circumference results changed by at most 0.03 s.d. per s.d.; the 16p11.2 duplication CNB accuracy slope and the across-CNV heterogeneity for CNB accuracy lost significance; several CNV x age x BMI (three-way) *P* values for height moved by orders of magnitude in both directions, so these terms are reported in Supplementary Table 1 but not interpreted.")

H2("Supplementary Methods")
H3("Ages of SSC relatives")
P("The age fields of the SSC version 15 phenotype tables give age at a single snapshot date (September 2012), about three years after the typical study visit. Visit age for siblings and parents was reconstructed as the proband's age at evaluation plus the difference in birth month between the relative and the proband; this reproduces the SSC's own tabulated sibling height *z* scores (*r* = 0.96).")
H3("Plausibility screen")
P("Heights recorded in metres were multiplied by 100. Heights outside 60-230 cm (together with the derived BMI), BMI outside 10-70 kg m^-2^, |height *z*| > 5, child |BMI *z*| > 5 and head circumference outside 30-70 cm or |*z*| > 5 were set to missing before any model was fitted. The screen was applied to the cross-sectional genomatrix and to the longitudinal Simons VIP series. Flagged records were listed for manual review and a correction sheet is applied automatically when filled in.")
H3("Longitudinal models")
P("In carriers under 18 years, the change in height *z* or head-circumference *z* from one visit to the next was regressed on BMI *z* at the first visit, adjusting for *z* at that visit, interval length, sex and, in pooled models, locus and cohort, with a child random intercept. A mixed GAM with s(age, by = BMI) gave the age-varying effect and its test against zero at any age; the same model with a constant BMI term gave the all-ages coefficient; linear mixed models with BMI x age-window terms gave window-specific coefficients (height: < 8, 8-13, 13-18 years; head circumference: 2-5, 5-18 years). Height used longitudinal visits of Simons VIP, Searchlight and Cardiff carriers (intervals >= 0.5 years); head circumference used the full Simons VIP measurement series plus Cardiff, G2MH and SSC carrier visits. 22q11.2 duplication children were too few (*n* <= 12) for separate estimates.")
H3("Autism diagnosis within CNV group")
P("Within each CNV group, the pooled overgrowth and undergrowth groups and the SSC (probands versus designated siblings), height, head-circumference and BMI *z* were compared between individuals with and without an autism diagnosis in GAMs *y* ~ autism + s(age) + sex, plus cohort and, in pooled groups, locus. The difference between the autism effect in a carrier group and that in SSC non-carriers was tested by pooling the carrier group with the non-carriers and fitting *y* ~ autism + locus + autism x carrier + s(age, by = carrier) + sex + cohort. Sensitivity models added each polygenic score, and all four, in the subset with scores.")
H3("Polygenic scores")
P("Weights were SBayesRC posterior effects^15^ (UK Biobank European HapMap3 LD reference, baseline-LD 2.2 annotations) derived from published summary statistics for adult BMI^16^, childhood obesity^17^ and height^18^, and from the April 2026 autism GWAS meta-analysis (iPSYCH, PGC, SPARK, SSC and MoBa; unpublished; the 2019 release is ref. 19). Scores were computed with PLINK 2^20^ on whole-genome sequence genotypes of G2MH carriers and on the SSC genotype set; for autism, SSC was scored with weights derived leaving the SSC out of the discovery GWAS, because the SSC contributes to that GWAS. Scores were residualized on ten ancestry principal components within cohort and standardized within cohort. Simons VIP, Searchlight and Cardiff carriers were not scored.")
H3("Sex and polygenic-score sensitivity analyses")
P("Confounding (Supplementary Table 5): for each trait and group, the carrier BMI slope and the CNV x BMI contrast versus unaffected controls were refitted on the individuals with all four scores, unadjusted; adding sex and sex x BMI; adding each score with its BMI interaction; adding all four; and all four plus sex. Stratification (Supplementary Table 4): the main-figure tests were repeated within sex and within below- and above-median halves of each score, carriers and controls stratified alike. Interactions (Supplementary Table 6): for each modifier (sex; each score as a continuous *z*), BMI x modifier was fitted within carriers (*y* ~ s(age) + BMI x modifier [+ locus]); power to detect an interaction as large as the carriers' own BMI effect was computed from the term's standard error (normal approximation) and interactions are reported only where that power was at least 80%.")
H3("Medication")
P("Current medication from the G2MH medications release was classified by drug name into antipsychotics, stimulant and other ADHD medication, ADHD alpha-agonists, antidepressants, antiepileptics and mood stabilizers, and anxiolytics; weight-gain-associated (antipsychotics, valproate, lithium, mirtazapine, gabapentinoids) and weight-loss-associated (stimulants, atomoxetine, topiramate, metformin, GLP-1 agonists) groupings were also formed. Within-carrier BMI slopes for height, head circumference, SRS, SCQ and CNB were refitted unadjusted, with class indicators, in carriers on no psychotropic, and with classes plus autism diagnosis. Associations of each class with BMI and with the trait were tested in age- and locus-adjusted GAMs. Controls have no medication data, so the carrier-control contrasts cannot be medication-adjusted.")
H3("Cognitive measures")
P("Penn CNB^13,14^ accuracy and speed scores were standardized against G2MH non-carriers (speed as the negative *z* of median correct response time); totals are the mean of subtest *z* scores over at least five subtests, and BMI was taken within three years of the battery. G2MH non-carriers with CNB data have no BMI, so no control contrast is available.")

H2("Supplementary Figures")
BR(); H3("Supplementary Fig. 1 | Prospective, age-varying effect of body mass on subsequent growth in CNV carriers under 18 years.")
P("Change in height *z* (WHO; top row) or head-circumference *z* (UK90; bottom row) from one visit to the next, per 1 s.d. of BMI *z* at the first visit, as a smooth function of age at that visit (line, 95% CI). Columns: 16p11.2 deletion, 16p11.2 duplication, 22q11.2 deletion and all carriers pooled (including 22q11.2 duplication children). Mixed GAM with a child random intercept, adjusted for *z* at the visit, interval length, sex and (pooled) locus and cohort; the age-varying *P* tests whether the BMI effect differs from zero at any age; 'all ages' is the same model with a single constant BMI coefficient (+/- s.e.). Grey band, 8-13 years. Height: 116, 48, 73 and 248 children (224, 84, 102 and 422 intervals); head circumference: 91, 46, 50 and 193 children (287, 159, 56 and 509 intervals). Two-sided tests. Statistics in Supplementary Table 3.")
IMG(file.path(HERE, "fig_supp_prospective.png"))
BR(); H3("Supplementary Fig. 2 | Social-communication scores against body mass in CNV carriers, unaffected relatives and autistic SSC probands.")
P("SRS total (*z* relative to SSC unaffected relatives; left) and SCQ lifetime total (*z* relative to SSC siblings; right), adjusted for age within group, against BMI *z*. **a**,**g**, Non-carriers: unaffected SSC siblings and parents (grey; *n* = 5,493 SRS, 1,134 SCQ) and SSC probands with autism and no CNV (black; *n* = 2,066 and 1,504); fitted lines with 95% CI and mean +/- s.e.m. in BMI bins. **b-e**,**h-k**, 16p11.2 deletion, 16p11.2 duplication, 22q11.2 deletion and 22q11.2 duplication carriers (points coloured by BMI tail: red >= 70th centile, grey 30th-70th, teal <= 30th; black line and band, linear fit with 95% CI; dashed grey, the unaffected fit); printed are the within-carrier BMI slope with its *P* value, the *P* value for its difference from unaffected relatives, and the slope in carriers without an autism diagnosis. **f**,**l**, BMI slope with 95% CI by group for all carriers (filled circles), carriers without autism (open circles) and with autism diagnosis as a covariate (triangles); asterisks, slopes differing from unaffected relatives at *P* < 0.05. Neither unaffected relatives nor autistic probands show a BMI slope (SRS +0.01 and +0.03; SCQ +0.01 and +0.03 s.d. per s.d.), whereas carriers do (all CNVs, SRS +0.24, SCQ +0.33). Two-sided GAM tests; bold, nominal *P* < 0.05.")
IMG(file.path(HERE, "fig_cognition_bmi_slopes.png"), w = 3.4)
BR(); H3("Supplementary Fig. 3 | Body mass and Penn CNB accuracy in CNV carriers.")
P("Penn Computerized Neurocognitive Battery accuracy total (mean *z* across subtests relative to G2MH non-carriers; at least five subtests), adjusted for age within group, against BMI *z* (measured within three years of the battery), in carriers of 16p11.2 deletion (**a**, *n* = 140), 16p11.2 duplication (**b**, *n* = 56), 22q11.2 deletion (**c**, *n* = 347) and 22q11.2 duplication (**d**, *n* = 142). Points coloured by BMI tail as in Supplementary Fig. 2; black line and band, linear fit with 95% CI; diamonds, mean +/- s.e.m. in BMI bins. Printed, the BMI slope (s.d. per s.d.; GAM *y* ~ s(age) + BMI) and its two-sided *P* value. Heterogeneity of the slope across the four CNVs (Wald test of locus x BMI): *F* = 2.02 on 3 d.f., *P* = 0.11. G2MH non-carriers with CNB data have no BMI, so no control panel is shown.")
IMG(file.path(HERE, "fig_supp_cnb_accuracy_total_bmi.png"))
BR(); H3("Supplementary Fig. 4 | Body mass and Penn CNB subtest performance in CNV carriers.")
P("**a**, Accuracy (ten subtests and the accuracy total). **b**, Speed (eleven subtests and the speed total; speed is the negative *z* of median correct response time, higher = faster). Columns, CNB measures; rows, 16p11.2 deletion, 16p11.2 duplication, 22q11.2 deletion and 22q11.2 duplication carriers (G2MH). Each panel plots the age-adjusted score against BMI *z* with the conventions of Supplementary Fig. 3 and prints the BMI slope (s.d. per s.d.) and its two-sided *P* value (bold, *P* < 0.05). *n* (accuracy total / speed total): 140/142, 56/56, 347/353, 142/142. No subtest or total shows significant heterogeneity of the slope across CNVs after the plausibility screen (accuracy total *P* = 0.11; speed total *P* = 0.94; all subtests *P* >= 0.086).")
IMG(file.path(HERE, "fig_supp_cnb_accuracy_bmi.png")); IMG(file.path(HERE, "fig_supp_cnb_speed_bmi.png"))
BR(); H3("Supplementary Fig. 5 | Height, head circumference and BMI by autism diagnosis within CNV group.")
P("Mean +/- s.e.m. of height *z* (**a**), head-circumference *z* (**b**) and BMI *z* (**c**) in carriers with (blue) versus without (grey) an autism diagnosis, for each CNV, the pooled overgrowth (16p11.2 deletion + 22q11.2 duplication) and undergrowth (16p11.2 duplication + 22q11.2 deletion) groups and, as the non-carrier comparison, SSC probands with autism versus SSC designated siblings. Numbers under the bars are *n*. Printed above each group is the age- and sex-adjusted autism effect (delta, s.d.; GAM *y* ~ autism + s(age) + sex, plus cohort and, for pooled groups, locus) with its two-sided *P* value (bold, *P* < 0.05). Carriers with autism are mostly children and carriers without include adult relatives; the age smooth addresses this and the head-circumference effect holds within children. The difference between each carrier group's autism effect and the proband-sibling difference (autism x carrier interaction), and the same contrasts with polygenic scores as covariates, are in Supplementary Tables 7 and 8.")
